// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests for ru-safe-halt: fold, classes (login, needs-you, unsafe), stored halt, live sim pages
// Flo: texts > verdict; sim overlays > guard result; nothing sent
// I/O: text and html > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const halt = @import("ru-safe-halt.zig"); const conf = @import("cf-conf-load.zig"); const lab = @import("cf-labl-load.zig"); const data = @import("st-stat-data.zig"); const mock = @import("te-mock-page.zig"); const zsim = @import("te-zsim-page.zig"); const snap = @import("ru-page-snap.zig"); const T = std.testing; const rig = @import("te-rigz-main.zig");
fn profOf(tmpz: *std.testing.TmpDir, buff: []u8) ![]const u8 { return std.fmt.bufPrint(buff, ".zig-cache/tmp/{s}/prof", .{tmpz.sub_path}); }
test "fold lowers ASCII and Vietnamese capitals" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); try T.expectEqualStrings("tài khoản bị khóa", try halt.lowFold(aren.allocator(), "TÀI KHOẢN BỊ KHÓA")); try T.expectEqualStrings("đăng nhập ở nơi khác", try halt.lowFold(aren.allocator(), "ĐĂNG NHẬP Ở NƠI KHÁC")); try T.expectEqualStrings("ưu tiên", try halt.lowFold(aren.allocator(), "ƯU TIÊN")); try T.expectEqualStrings("abc 123 ✓", try halt.lowFold(aren.allocator(), "AbC 123 ✓")); try T.expectEqualStrings("\xff\xfe", try halt.lowFold(aren.allocator(), "\xff\xfe")); }
test "classes: captcha needs you, lock is unsafe, QR page is login, clean is okay" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); const cfg: conf.Conf = .{}; const reg = try lab.builtin(alo); const cap = try halt.check(alo, cfg, &reg, "Hoàn thành CAPTCHA để tiếp tục"); try T.expect(cap.kind == .need); const lck = try halt.check(alo, cfg, &reg, "Tài khoản của bạn đã bị khóa tạm thời"); try T.expect(lck.kind == .unsf); const eng = try halt.check(alo, cfg, &reg, "Your account is Suspended"); try T.expect(eng.kind == .unsf); const els = try halt.check(alo, cfg, &reg, "Tài khoản đã được đăng nhập ở nơi khác"); try T.expect(els.kind == .need); const qr = try halt.check(alo, cfg, &reg, "ĐĂNG NHẬP TÀI KHOẢN ZALO xác minh"); try T.expect(qr.kind == .login); const ok = try halt.check(alo, cfg, &reg, "Mom: Dinner at 7?"); try T.expect(ok.kind == .okay); }
test "owner extra words count as unsafe" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); var cfg: conf.Conf = .{}; cfg.halt_word_list = &.{"khẩn cấp"}; const reg = try lab.builtin(alo); const ver = try halt.check(alo, cfg, &reg, "THÔNG BÁO KHẨN CẤP"); try T.expect(ver.kind == .unsf); try T.expectEqualStrings("khẩn cấp", ver.word); }
test "guardText stores flag and class, later clean text still halts until cleared" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); const cfg: conf.Conf = .{}; const reg = try lab.builtin(alo); var sto = try data.Stor.open(T.allocator, ":memory:"); defer sto.close(); try T.expectError(error.Halted, halt.guardText(alo, cfg, &reg, &sto, 10, "Hoàn thành captcha")); try T.expect(try halt.classOf(&sto, alo) == .need); const why = (try sto.haltGet(T.allocator)).?; defer T.allocator.free(why); try T.expectEqualStrings("captcha", why); try T.expectError(error.Halted, halt.guardText(alo, cfg, &reg, &sto, 11, "all fine now")); try sto.haltClear(); try halt.guardText(alo, cfg, &reg, &sto, 12, "all fine now"); try sto.metaSet("halt_class", ""); try T.expectError(error.Halted, halt.guardText(alo, cfg, &reg, &sto, 13, "tài khoản bị khóa")); try T.expect(try halt.classOf(&sto, alo) == .unsf); }
test "guardText login page is NeedLogin and does not store a halt" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); const cfg: conf.Conf = .{}; const reg = try lab.builtin(alo); var sto = try data.Stor.open(T.allocator, ":memory:"); defer sto.close(); try T.expectError(error.NeedLogin, halt.guardText(alo, cfg, &reg, &sto, 1, "Đăng nhập tài khoản Zalo")); try T.expect((try sto.haltGet(T.allocator)) == null); }
test "M4 live on the sim: overlays halt, login needs QR, chat is clear" { const gpa = T.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var aren = std.heap.ArenaAllocator.init(gpa); defer aren.deinit(); const alo = aren.allocator(); const page = try zsim.html(alo); var mok = try mock.start(gpa, T.io, try profOf(&tmpz, &buff), page); defer mok.stop(); const cfg: conf.Conf = .{}; const reg = try lab.builtin(alo); var sto = try data.Stor.open(gpa, ":memory:"); defer sto.close(); try halt.guard(alo, cfg, &reg, &sto, mok.conn, 1); _ = try snap.evalStr(alo, mok.conn, "Z.overlay('login')"); try T.expectError(error.NeedLogin, halt.guard(alo, cfg, &reg, &sto, mok.conn, 2)); _ = try snap.evalStr(alo, mok.conn, "Z.overlay('lock')"); try T.expectError(error.Halted, halt.guard(alo, cfg, &reg, &sto, mok.conn, 3)); try T.expect(try halt.classOf(&sto, alo) == .unsf); try sto.haltClear(); _ = try snap.evalStr(alo, mok.conn, "Z.overlay('captcha')"); try T.expectError(error.Halted, halt.guard(alo, cfg, &reg, &sto, mok.conn, 4)); try T.expect(try halt.classOf(&sto, alo) == .need); try sto.haltClear(); _ = try snap.evalStr(alo, mok.conn, "Z.overlay('kick')"); try T.expectError(error.Halted, halt.guard(alo, cfg, &reg, &sto, mok.conn, 5)); try sto.haltClear(); _ = try snap.evalStr(alo, mok.conn, "Z.clearOverlay()"); try halt.guard(alo, cfg, &reg, &sto, mok.conn, 6); }
test "a chat message that says captcha does not halt when message selectors are known" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); const alo = rg.aren.allocator(); _ = try rg.js("Z.chats[0].msgs.push(mk('them','text','please solve the captcha and verify the bank'));openChat(Z.chats[0]);'x'"); var ses = rg.ses(rig.cfgOf(), .live); try halt.guard(alo, ses.cfg, &ses.reg, ses.sto, ses.conn, 1); ses.reg.ext = .{}; try T.expectError(error.Halted, halt.guard(alo, ses.cfg, &ses.reg, ses.sto, ses.conn, 2)); }
